;$(document).ready( function() {
    // 工具提示
    if ($('[data-bs-toggle="tooltip"]')[0]) {
        $('[data-bs-toggle="tooltip"]').tooltip({
	        "container" : 'body',
	    });
    }
    
    // pop提示
    if ($('[data-bs-toggle="popover"]')[0]) {
        $('[data-bs-toggle="popover"]').popover({
            container: 'body'
        });
    }
  
    // Card最大化
    $(document).on('click', '.card-btn-fullscreen', function(){
        $(this).closest('.card').toggleClass('card-fullscreen');
    });
    
    // Card收缩/展开
    $(document).on('click', '.card-btn-slide', function(){
        $(this).toggleClass('rotate-180').closest('.card').find('.card-body').slideToggle();
    });
    
    // Card刷新
    $(document).on('click', '.card-btn-reload', function(e) {
        e.preventDefault();
        var url = $(this).attr('href');
        var $card = $(this).closest('.card');
        
        if (url == "#" | url == "#!") {
            return;
        }
        
        var l = $card.lyearloading({
            opacity: 0.1,
            spinnerSize: 'nm'
        });
        $card.find('.card-body').load(url, function(){
            l.destroy();
        });
    });
    
    // Card关闭
    $(document).on('click', '.card-btn-close', function() {
        $(this).closest('.card').fadeOut(600, function() {
            if ($(this).parent().children().length == 1) {
                $(this).parent().remove();
            } else {
                $(this).remove();
            }
        });
    });
  
    /**
     * 如果页面中需要用到滚动条，请先导入perfect-scrollbar.min.js
     */ 
    if($('.lyear-scroll')[0]) {
        $('.lyear-scroll').each(function(){
            new PerfectScrollbar(this, {
	        	swipeEasing: false,
	        	suppressScrollX: true
	        });
        });
    }
  
    // 颜色选取
	jQuery('.js-colorpicker').each(function() {
		var $colorpicker = jQuery(this);
		$colorpicker.colorpicker({
			'format': $colorpicker.data('colorpicker-mode') ? $colorpicker.data('colorpicker-mode') : 'auto',
            'horizontal' : $colorpicker.data('colorpicker-horizontal') ? $colorpicker.data('colorpicker-horizontal') : false
		});
	});

    // 时间选择
    jQuery('.js-datetimepicker').each(function() {
        var $input = jQuery(this);
        var dateType = $input.attr("dateType");
        var startView = 2;
        var minuteStep = 1;
        var minView = 0 ;
        if(dateType!==undefined&&dateType!==null&&dateType!==""){
            if(dateType == "year"){
                minView = 4;
                startView = 4;
            }else if(dateType == "month"){
                minView = 3;
                startView = 3;
            }else if(dateType == "day"){
                minView = 2;
                startView = 2;
            }else if(dateType == "hour"){
                minView = 1;
                startView = 2;
            }else{
                minView = 0;
                startView = 2;
                var ms = $input.attr("minuteStep");
                if(ms!==undefined&&ms!==null&&ms!==""){
                    minuteStep =ms
                }
            }
        }else{
            minView = 0;
        }
        $input.datetimepicker({
            autoclose:true,
            fontAwesome:'font-awesome',//指定
            format: $input.data('format') ? $input.data('format') : false,
            bootcssVer:3, //在这里添加bootcssVer:3 就能解决箭头问题了
            startView: startView,
            minView:minView,
            minuteStep:parseInt(minuteStep),
            language: "zh-CN",
        });
    });

    // 日期选择
    jQuery('.js-datepicker').each(function() {
        var $input = jQuery(this);
        $input.datepicker({
            weekStart: 1,
            autoclose: true,
            todayHighlight: true,
            language: 'zh-CN',
        });
    });
    //微调器组件
    $(".touchSpin").TouchSpin({});
    
    // 标签
	$('.js-tags-input').each(function() {
        var $this = $(this);
        $this.tagsInput({
			height: $this.data('height') ? $this.data('height') : '100%',
			width: '100%',
			defaultText: $this.attr("placeholder"),
			removeWithBackspace: true,
			delimiter: [',']
		});
    });
  
    // 复选框全选
    $(document).on('change', '#check-all', function () {
        if ($boxname = $(this).data('name')) {
            $(this).closest('table').find("input[name='" + $boxname + "']").prop('checked', $(this).prop("checked"));
        } else {
            $(this).closest('table').find(".form-check input[type='checkbox']").prop('checked', $(this).prop("checked"));
        }
    });
    
    // iframe打开tab
 	$(document).on('click', '.js-create-tab', function(){
 	    parent.$(parent.document).data('multitabs').create({
 	        iframe : true,
 	        title : $(this).data('title') ? $(this).data('title') : '标题',
 	        url : $(this).data('url') ? $(this).data('url') : 'lyear-main.html'
 	    }, true);
 	});
    
});

// 参考国外模板的写法，获取当前的配置，以data-*（*指插件原有的配置名）
getDataOptions = function(el, castList) {
    var options = {};
    
    $.each( $(el).data(), function(key, value){
    
        key = dataToOption(key);
        
        if ( key == 'provide' ) {
            return;
        }
        options[key] = value;
    });
    
    return options;
}

dataToOption = function(name) {
    return name.replace(/-([a-z])/g, function(x){return x[1].toUpperCase();});
}
if (window.frames.length != parent.frames.length) {
    if (parent.$._data(parent.$('.mt-tab-content')[0], "events") === undefined || parent.$._data(parent.$('.mt-tab-content')[0], "events").removeNode === undefined) {
        var $loading = parent.$("#lyear-loading");
        parent.$('.mt-tab-content').on('removeNode', function() {    
            if ($loading.is(":visible")) {
                $loading.fadeOut('slow');
            }
        });
    }
    window.onpagehide = function () {
        parent.$('#lyear-loading').fadeIn(1);
    };
}